import{_ as a,o,c as i,a2 as t}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"reference/changelog.md","filePath":"reference/changelog.md","lastUpdated":1787084291000}'),n={name:"reference/changelog.md"};function r(d,e,l,s,c,h){return o(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><h2 id="_0-1-1-2026-08-18" tabindex="-1">[0.1.1] - 2026-08-18 <a class="header-anchor" href="#_0-1-1-2026-08-18" aria-label="Permalink to &quot;[0.1.1] - 2026-08-18&quot;">​</a></h2><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Documentation site at <a href="https://osm-mcp.ni-c.de" target="_blank" rel="noreferrer">https://osm-mcp.ni-c.de</a>: guides, a complete tool reference generated from the actual schemas, FAQ and this changelog.</li><li>Architecture diagram and demo recording, each generated from a single source (<code>npm run assets</code>, <code>docs/demo.tape</code>) and verified in CI.</li><li>Fully automated release pipeline: npm publishing with provenance via Trusted Publishing, GitHub releases from the changelog, MCP Registry and multi-arch GHCR publishing on tag push.</li></ul><h2 id="_0-1-0-2026-08-18" tabindex="-1">[0.1.0] - 2026-08-18 <a class="header-anchor" href="#_0-1-0-2026-08-18" aria-label="Permalink to &quot;[0.1.0] - 2026-08-18&quot;">​</a></h2><h3 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h3><ul><li>The optional <code>ORS_API_KEY</code> is now stripped from every tool result as a last line of defense: it travels in an <code>Authorization</code> header, so an upstream (or a misconfigured <code>ORS_BASE_URL</code> host) echoing the request could previously have leaked it into the model context through an error body. URL-style key parameters are additionally redacted from sanitized error bodies.</li><li>The <code>mcp-publisher</code> binary in the release workflows is now version-pinned and checksum-verified instead of floating on <code>releases/latest</code> — it runs with the job&#39;s OIDC identity, which proves registry ownership.</li><li>The npm/registry publish in <code>release.yml</code> now waits for its own Trivy container scan instead of racing the scan in <code>ci.yml</code>.</li><li>The response cache now has an aggregate 32 MB byte budget on top of the entry cap; the caps alone allowed ~500 MB of retained upstream JSON.</li><li>Every tool call gets a 120 s wall-clock deadline: many-waypoint requests behind the 1 req/s geocoding limiter could previously occupy the queue for minutes past any client timeout.</li><li>POI core tags are truncated with the same 500-char value budget as <code>poi_details</code> tags, and <code>countrycodes</code> input length is bounded.</li></ul><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><p>Validated base URLs are returned in their WHATWG-normalized form instead of the raw input string.</p></li><li><p>The container now exits promptly on SIGTERM/SIGINT — as PID 1, Node gets no default signal handling, so <code>docker stop</code> used to wait out its grace period and SIGKILL.</p></li><li><p>The optional <code>ORS_API_KEY</code> is now removed from the environment before any configuration validation can throw. Previously a caller that caught the <code>ConfigError</code> (e.g. for an invalid <code>OSM_CACHE_TTL</code>) would keep running with the key still in <code>process.env</code> — readable in <code>/proc/&lt;pid&gt;/environ</code> and inherited by child processes. (Same finding as audiobookshelf-mcp PR #2.)</p></li><li><p>Invalid base-URL and <code>OSM_CACHE_TTL</code> values are no longer echoed in error messages — an API key pasted into the wrong environment variable would have been printed verbatim into the MCP host&#39;s log.</p></li><li><p><code>isLoopbackHost</code> now strips IPv6 brackets generically instead of matching only the literal <code>[::1]</code>.</p></li></ul><h3 id="added-1" tabindex="-1">Added <a class="header-anchor" href="#added-1" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Initial implementation: 11 read-only OpenStreetMap tools — geocoding (Nominatim + Photon), routing/matrix/trip optimization via the FOSSGIS OSRM instance with correct <code>routed-{car,bike,foot}</code> profile prefixes, isochrones via Valhalla (OpenRouteService optional via <code>ORS_API_KEY</code>), POI search and details via Overpass with mirror failover, plus offline straight-line distance and openstreetmap.org link tools.</li><li>Per-service rate limiting, in-memory response caching and a mandatory identifying User-Agent, keeping the server inside the published usage policies of the public OSM services.</li></ul>',11)])])}const g=a(n,[["render",r]]);export{u as __pageData,g as default};
